local R=loadstring(game:HttpGet('https://sirius.menu/rayfield'))()local P=game:GetService("Players")local recording=false local recordedActions={}local hookedRemotes={}local startTime=tick()local function serialize(v,d)d=d or 0 if d>4 then return "..." end local t=typeof(v)if t=="string"then return string.format("%q",v)elseif t=="number"or t=="boolean"then return tostring(v)elseif t=="nil"then return "nil"elseif t=="Instance"then return v:GetFullName()elseif t=="Vector3"then return string.format("Vector3.new(%0.2f, %0.2f, %0.2f)",v.X,v.Y,v.Z)elseif t=="CFrame"then return "CFrame.new("..tostring(v.Position)..")"elseif t=="table"then local p={}local c=0 for k,x in pairs(v)do c=c+1 if c>20 then table.insert(p,"...")break end table.insert(p,tostring(k).." = "..serialize(x,d+1))end return "{"..table.concat(p,", ").."}"end return tostring(v)end local function buildOutput()if #recordedActions==0 then return "-- No actions recorded yet --" end local l={"-- Action Recorder Output","-- Recorded: "..os.date("%Y-%m-%d %H:%M:%S"),"-- Total actions: "..#recordedActions,""}for i,a in ipairs(recordedActions)do table.insert(l,string.format("[%d] (t=%.3fs) %s:%s",i,a.time,a.type,a.name))table.insert(l,"    Path: "..a.path)if a.args and #a.args>0 then for j,g in ipairs(a.args)do table.insert(l,string.format("    arg[%d] = %s",j,serialize(g)))end else table.insert(l,"    (no arguments)")end table.insert(l,"")end return table.concat(l,"\n")end local function hookRemote(r)if hookedRemotes[r]then return end hookedRemotes[r]=true if r:IsA("RemoteEvent")then local mt=getrawmetatable(game)if mt and not mt.___hooked then local old=mt.__namecall setreadonly(mt,false)mt.__namecall=newcclosure(function(s,...)local m=getnamecallmethod()if recording and s==r and m=="FireServer"then local args={...}table.insert(recordedActions,{time=tick()-startTime,type="RemoteEvent",name=r.Name,path=r:GetFullName(),args=args})end return old(s,...)end)setreadonly(mt,true)mt.___hooked=true end elseif r:IsA("RemoteFunction")then local mt=getrawmetatable(game)if mt and not mt.___hooked_rf then local old=mt.__namecall setreadonly(mt,false)mt.__namecall=newcclosure(function(s,...)local m=getnamecallmethod()if recording and s==r and m=="InvokeServer"then local args={...}table.insert(recordedActions,{time=tick()-startTime,type="RemoteFunction",name=r.Name,path=r:GetFullName(),args=args})end return old(s,...)end)setreadonly(mt,true)mt.___hooked_rf=true end end end local function scanAll()local c=0 for _,o in ipairs(game:GetDescendants())do if o:IsA("RemoteEvent")or o:IsA("RemoteFunction")then hookRemote(o)c=c+1 end end return c end local function copyToClipboard(t)if setclipboard then setclipboard(t)return true elseif toclipboard then toclipboard(t)return true end return false end local W=R:CreateWindow({Name="Action Recorder",LoadingTitle="Loading...",LoadingSubtitle="by you",ConfigurationSaving={Enabled=false},KeySystem=false})local T=W:CreateTab("Recorder",4483362458)local S=T:CreateLabel("Status: Idle")T:CreateButton({Name="Start Recording",Callback=function()recordedActions={}startTime=tick()recording=true S:Set("Status: Recording...")R:Notify({Title="Recorder",Content="Recording started",Duration=3})end})T:CreateButton({Name="Stop Recording",Callback=function()recording=false S:Set(string.format("Status: Stopped (%d actions)",#recordedActions))R:Notify({Title="Recorder",Content="Stopped. Recorded "..#recordedActions.." actions.",Duration=3})end})T:CreateButton({Name="Scan & Hook Remotes",Callback=function()local n=scanAll()R:Notify({Title="Recorder",Content="Hooked "..n.." remotes.",Duration=3})end})T:CreateButton({Name="Copy Output to Clipboard",Callback=function()local o=buildOutput()if copyToClipboard(o)then R:Notify({Title="Recorder",Content="Output copied ("..#recordedActions.." actions)",Duration=3})else R:Notify({Title="Recorder",Content="Clipboard not available!",Duration=4})end end})T:CreateButton({Name="Clear Recorded Actions",Callback=function()recordedActions={}S:Set("Status: Cleared")end})local O=T:CreateInput({Name="Output Preview",PlaceholderText="Click 'Copy Output' to get results",RemoveTextAfterFocusLost=false,Callback=function()end})task.spawn(function()while task.wait(2)do local p=buildOutput()if #p>500 then p=p:sub(1,500).."\n... (truncated)"end pcall(function()O:Set(p)end)end end)game.DescendantAdded:Connect(function(o)if o:IsA("RemoteEvent")or o:IsA("RemoteFunction")then hookRemote(o)end end)scanAll()R:Notify({Title="Action Recorder",Content="Loaded.",Duration=4})
